/* PLT-Edu · Tiếng Anh – Sổ tay ngữ pháp A1 → C1 (dùng chung mọi cấp)
   Mỗi chủ điểm: id, lv, ten (tiếng Việt), en, y (giải thích HTML), qs (câu luyện: mc / fill / order) */
(function () {
  'use strict';
  const sp = PLT.LANG.sp;
  const F = (x) => `<div class="zh-formula small">${x.split(' + ').map((p) => `<span>${p}</span>`).join('<i>+</i>')}</div>`;
  const ex = (a) => `<ul>${a.map(([e, v]) => `<li>${e} ${sp(e.replace(/\*/g, ''))}<br><span class="muted">${v}</span></li>`).join('')}</ul>`;
  const tip = (x) => `<div class="zh-tip">${x}</div>`;
  const tbl = (h, rows) => `<div class="zh-scroll"><table class="dtable full zh-tb"><tr>${h.map((x) => `<th>${x}</th>`).join('')}</tr>${rows.map((r) => `<tr>${r.map((c) => `<td>${c}</td>`).join('')}</tr>`).join('')}</table></div>`;
  const m = (q, a, d, e) => ['mc', q, a, d, e];
  const f = (q, a, e) => ['fill', q, a, e];
  const o = (q, p, e) => ['order', q, p, e];
  const G = [];
  const add = (id, lv, ten, en, y, qs) => G.push({ id, lv, ten, en, y, qs });

  /* ===================== A1 ===================== */
  add('to-be', 'A1', 'Động từ to be', 'am / is / are',
    `<h4>Công thức</h4>${tbl(['Chủ ngữ', 'Khẳng định', 'Phủ định', 'Câu hỏi'], [['I', 'I am (I\'m)', 'I am not', 'Am I…?'], ['He / She / It', 'is (\'s)', 'is not (isn\'t)', 'Is he…?'], ['You / We / They', 'are (\'re)', 'are not (aren\'t)', 'Are you…?']])}
    <h4>Dùng để</h4><p>Nói tên, tuổi, nghề, quốc tịch, tính chất, vị trí.</p>${ex([['I am a *student*.', 'Tôi là học sinh.'], ['She is *twenty* years old.', 'Cô ấy 20 tuổi.'], ['Are you from *Vietnam*?', 'Bạn đến từ Việt Nam à?']])}
    ${tip('⚠️ Người Việt hay bỏ to be: ❌ <i>I happy.</i> → ✅ <i>I am happy.</i> Tiếng Anh câu nào cũng cần động từ.')}`,
    [m('She ___ a teacher.', 'is', ['am', 'are', 'be'], 'She → is.'), m('They ___ at home.', 'are', ['is', 'am', 'be'], 'They → are.'), m('Câu đúng là?', 'I am very tired.', ['I very tired.', 'I is very tired.', 'I are very tired.'], 'Không được bỏ to be.'), f('___ you a doctor? (Viết từ còn thiếu)', 'Are', 'You → Are.'), m('He ___ not my brother.', 'is', ['are', 'am', 'do'], 'He is not.'), o('Sắp xếp: “Chúng tôi không mệt.”', ['We', 'are', 'not', 'tired.'], 'We are not tired.')]);
  add('hien-tai-don', 'A1', 'Thì hiện tại đơn', 'Present simple',
    `<h4>Công thức</h4>${F('S + V(s/es)')}${F('S + do/does not + V')}${F('Do/Does + S + V?')}
    <h4>Dùng để</h4><ul><li>Thói quen, việc lặp lại: <i>every day, usually, often</i></li><li>Sự thật, lịch trình cố định</li></ul>${ex([['She *works* at a *bank*.', 'Cô ấy làm ở ngân hàng.'], ['I don\'t drink *coffee*.', 'Tôi không uống cà phê.'], ['Does he play *football*?', 'Anh ấy có chơi bóng đá không?']])}
    ${tbl(['Thêm', 'Khi động từ tận cùng', 'Ví dụ'], [['-es', 's, sh, ch, x, o', 'watches, goes, fixes'], ['-ies', 'phụ âm + y', 'study → studies'], ['-s', 'còn lại', 'works, plays'], ['bất quy tắc', 'have', 'has']])}${tip('⚠️ Chủ ngữ ngôi 3 số ít (he, she, it, Nam) mới thêm -s. Sau does/doesn\'t, động từ trở về nguyên mẫu: ❌ <i>Does she works?</i>')}`,
    [m('He ___ to work by bus.', 'goes', ['go', 'gos', 'going'], 'He → goes.'), m('My mother ___ TV every night.', 'watches', ['watch', 'watchs', 'watching'], 'ch → -es.'), m('They ___ like spicy food.', "don't", ["doesn't", "isn't", "aren't"], 'They → don\'t.'), m('___ she speak English?', 'Does', ['Do', 'Is', 'Are'], 'She → Does.'), f('He ___ (study) English every day.', 'studies', 'phụ âm + y → ies.'), m('Câu đúng là?', 'Does he live here?', ['Does he lives here?', 'Do he live here?', 'Is he live here?'], 'Sau Does dùng V nguyên mẫu.')]);
  add('hien-tai-tiep-dien', 'A1', 'Thì hiện tại tiếp diễn', 'Present continuous',
    `<h4>Công thức</h4>${F('S + am/is/are + V-ing')}<h4>Dùng để</h4><ul><li>Việc đang xảy ra lúc nói: <i>now, right now, at the moment, Look!</i></li><li>Việc tạm thời dạo này; kế hoạch đã sắp xếp (A2)</li></ul>${ex([['I am *reading* a *book* now.', 'Tôi đang đọc sách.'], ['Look! It\'s *raining*.', 'Nhìn kìa! Trời đang mưa.'], ['What are you *doing*?', 'Bạn đang làm gì vậy?']])}
    ${tip('✍️ Thêm -ing: bỏ e câm (make → making), gấp đôi phụ âm cuối khi trước nó là 1 nguyên âm nhấn (run → running, sit → sitting).<br>⚠️ Động từ trạng thái (know, like, want, need, believe) thường không dùng -ing: ❌ <i>I am knowing</i>.')}`,
    [m('Listen! The baby ___.', 'is crying', ['cries', 'cry', 'are crying'], 'Đang xảy ra → is crying.'), m('They ___ football now.', 'are playing', ['play', 'is playing', 'plays'], 'now → are playing.'), f('run → ___ (V-ing)', 'running', 'Gấp đôi n.'), m('Câu đúng là?', 'I want a coffee.', ['I am wanting a coffee.', 'I wanting a coffee.', 'I am want a coffee.'], 'want là động từ trạng thái.'), m('She usually walks, but today she ___ a taxi.', 'is taking', ['takes', 'take', 'taking'], 'today → tạm thời.'), o('Sắp xếp: “Bạn đang làm gì?”', ['What', 'are', 'you', 'doing?'], 'What are you doing?')]);
  add('mao-tu', 'A1', 'Mạo từ a / an / the', 'Articles',
    `${tbl(['Mạo từ', 'Dùng khi', 'Ví dụ'], [['a', 'danh từ đếm được số ít, nhắc lần đầu, bắt đầu bằng <b>âm</b> phụ âm', 'a book, a university /juː/'], ['an', 'bắt đầu bằng <b>âm</b> nguyên âm', 'an apple, an hour /aʊ/'], ['the', 'cả hai người đều biết vật nào, nhắc lần thứ hai, duy nhất', 'the sun, the book on the table'], ['không dùng', 'nói chung chung với số nhiều / không đếm được', 'I like cats. Water is important.']])}
    ${ex([['I have *a* *dog*. *The* dog is very *cute*.', 'Tôi có một con chó. Con chó rất dễ thương.'], ['She is *an* *engineer*.', 'Cô ấy là kỹ sư.']])}${tip('⚠️ Nói nghề phải có a/an: ❌ <i>He is doctor.</i> → ✅ <i>He is a doctor.</i>')}`,
    [m('She is ___ engineer.', 'an', ['a', 'the', '(không điền)'], 'engineer bắt đầu bằng âm nguyên âm.'), m('I waited for ___ hour.', 'an', ['a', 'the', '(không điền)'], 'hour: h câm.'), m('He studies at ___ university.', 'a', ['an', 'the', '(không điền)'], 'university /juː/ → âm phụ âm.'), m('___ moon is beautiful tonight.', 'The', ['A', 'An', '(không điền)'], 'Duy nhất → the.'), m('Câu đúng là?', 'My father is a driver.', ['My father is driver.', 'My father is the driver of job.', 'My father is an driver.'], 'Nghề → a/an.'), m('I love ___ music.', '(không điền)', ['a', 'an', 'the'], 'Nói chung → không mạo từ.')]);
  add('danh-tu-dem', 'A1', 'Danh từ đếm được – không đếm được', 'some / any / much / many',
    `${tbl(['', 'Đếm được (book, apple)', 'Không đếm được (water, money, rice)'], [['Số nhiều', 'books, apples', 'không có số nhiều'], ['Câu khẳng định', 'some apples, many apples', 'some water, a lot of water'], ['Phủ định / câu hỏi', 'any apples? / not many', 'any water? / not much'], ['Hỏi số lượng', 'How many apples?', 'How much water?']])}
    ${ex([['There are *some* *eggs* in the fridge.', 'Có vài quả trứng trong tủ lạnh.'], ['I don\'t have *much* *time*.', 'Tôi không có nhiều thời gian.'], ['How *much* is it?', 'Cái này bao nhiêu tiền?']])}${tip('⚠️ Không đếm được trong tiếng Anh nhưng đếm được trong tiếng Việt: <b>information, advice, news, furniture, equipment</b>. ❌ <i>an information</i> → ✅ <i>a piece of information</i>.')}`,
    [m('How ___ people are there?', 'many', ['much', 'any', 'some'], 'people đếm được.'), m('How ___ money do you need?', 'much', ['many', 'any', 'a'], 'money không đếm được.'), m('Are there ___ students in the room?', 'any', ['some', 'much', 'a'], 'Câu hỏi → any.'), m('Câu đúng là?', 'Can you give me some advice?', ['Can you give me an advice?', 'Can you give me some advices?', 'Can you give me many advice?'], 'advice không đếm được.'), m('We need ___ equipment for the new office.', 'some', ['an', 'many', 'a'], 'equipment không đếm được.'), f('child → số nhiều: ___', 'children', 'Bất quy tắc.')]);
  add('so-huu', 'A1', 'Đại từ và tính từ sở hữu', "I / me / my / mine, 's",
    `${tbl(['Chủ ngữ', 'Tân ngữ', 'Tính từ sở hữu', 'Đại từ sở hữu'], [['I', 'me', 'my', 'mine'], ['you', 'you', 'your', 'yours'], ['he', 'him', 'his', 'his'], ['she', 'her', 'her', 'hers'], ['it', 'it', 'its', '—'], ['we', 'us', 'our', 'ours'], ['they', 'them', 'their', 'theirs']])}
    ${ex([['This is *my* *phone*. It\'s *mine*.', 'Đây là điện thoại của tôi. Nó là của tôi.'], ['Please call *him*.', 'Làm ơn gọi cho anh ấy.'], ['*Lan\'s* *brother* is a *doctor*.', 'Anh trai của Lan là bác sĩ.']])}${tip('⚠️ Người Việt hay nhầm he/she và his/her khi nói nhanh. Chú ý: <b>its</b> (của nó) ≠ <b>it\'s</b> (it is).')}`,
    [m('This is my sister. ___ name is Mai.', 'Her', ['His', 'She', 'Hers'], 'Của cô ấy → Her.'), m('Can you help ___?', 'me', ['I', 'my', 'mine'], 'Sau động từ → tân ngữ.'), m('That book is not mine. It\'s ___.', 'hers', ['her', 'she', 'his book her'], 'Đại từ sở hữu.'), m('The dog is wagging ___ tail.', 'its', ["it's", 'it', 'his'], 'its = của nó.'), m('“Nhà của bố mẹ tôi” là?', "my parents' house", ["my parent's house", 'my parents house', "my parents's house"], 'Số nhiều có s → chỉ thêm \'.'), o('Sắp xếp: “Họ là bạn của chúng tôi.”', ['They', 'are', 'our', 'friends.'], 'They are our friends.')]);
  add('gioi-tu', 'A1', 'Giới từ thời gian và nơi chốn', 'in / on / at',
    `${tbl(['', 'Thời gian', 'Nơi chốn'], [['<b>at</b>', 'giờ, thời điểm: at 7 o\'clock, at night, at the weekend (Anh)', 'điểm cụ thể: at home, at work, at the bus stop'], ['<b>on</b>', 'ngày, thứ: on Monday, on 2nd May, on my birthday', 'bề mặt, tầng, đường: on the table, on the 3rd floor, on Le Loi Street'], ['<b>in</b>', 'tháng, năm, mùa, buổi: in May, in 2026, in the morning', 'bên trong, thành phố, quốc gia: in the box, in Hanoi']])}
    ${ex([['I get up *at* *six*.', 'Tôi dậy lúc 6 giờ.'], ['My birthday is *on* *Friday*.', 'Sinh nhật tôi vào thứ Sáu.'], ['She lives *in* *Da* *Nang*.', 'Cô ấy sống ở Đà Nẵng.']])}`,
    [m('The meeting is ___ 9 a.m.', 'at', ['in', 'on', 'by'], 'Giờ → at.'), m('I was born ___ 1995.', 'in', ['on', 'at', 'by'], 'Năm → in.'), m('See you ___ Monday!', 'on', ['in', 'at', 'by'], 'Thứ → on.'), m('He works ___ a bank.', 'at', ['on', 'by', 'of'], 'Nơi làm việc → at.'), m('The keys are ___ the table.', 'on', ['in', 'at', 'of'], 'Bề mặt → on.'), m('We often go out ___ the evening.', 'in', ['on', 'at', 'by'], 'Buổi → in the evening.')]);
  add('there-is', 'A1', 'There is / There are', 'Có cái gì ở đâu',
    `${F('There is + danh từ số ít / không đếm được')}${F('There are + danh từ số nhiều')}${ex([['There is a *bank* near my *house*.', 'Có một ngân hàng gần nhà tôi.'], ['There are *three* *people* in my *family*.', 'Nhà tôi có ba người.'], ['Is there a *toilet* here?', 'Ở đây có nhà vệ sinh không?']])}
    ${tip('⚠️ Không dùng "have" để nói "ở đâu đó có": ❌ <i>In my room has a bed.</i> → ✅ <i>There is a bed in my room.</i>')}`,
    [m('___ a cat under the table.', 'There is', ['There are', 'It has', 'Have'], 'a cat → There is.'), m('___ many students in my class.', 'There are', ['There is', 'It has', 'They have'], 'Số nhiều → There are.'), m('Câu đúng là?', 'There is a park near here.', ['Near here has a park.', 'It has a park near here.', 'There are a park near here.'], '“Có” chỉ sự tồn tại → there is.'), m('Is there ___ milk in the fridge?', 'any', ['a', 'many', 'some of'], 'Câu hỏi + không đếm được.'), m('___ there any questions?', 'Are', ['Is', 'Do', 'Have'], 'questions số nhiều.'), o('Sắp xếp: “Có hai phòng ngủ.”', ['There', 'are', 'two', 'bedrooms.'], 'There are two bedrooms.')]);

  /* ===================== A2 ===================== */
  add('qua-khu-don', 'A2', 'Thì quá khứ đơn', 'Past simple',
    `<h4>Công thức</h4>${F('S + V2/V-ed')}${F('S + did not + V')}${F('Did + S + V?')}<p>Dùng cho việc <b>đã xong ở thời điểm xác định</b> trong quá khứ: yesterday, last week, in 2020, two days ago.</p>
    ${ex([['I *visited* *Hue* last *summer*.', 'Mùa hè năm ngoái tôi đã đi Huế.'], ['She didn\'t *go* to *work* yesterday.', 'Hôm qua cô ấy không đi làm.'], ['Did you *see* the *match*?', 'Bạn có xem trận đấu không?']])}
    ${tbl(['V1', 'V2', 'Nghĩa'], [['go', 'went', 'đi'], ['have', 'had', 'có'], ['buy', 'bought', 'mua'], ['see', 'saw', 'thấy'], ['take', 'took', 'lấy'], ['make', 'made', 'làm'], ['eat', 'ate', 'ăn'], ['write', 'wrote', 'viết']])}${tip('⚠️ Sau did/didn\'t, động từ nguyên mẫu: ❌ <i>Did you went?</i> → ✅ <i>Did you go?</i>')}`,
    [m('We ___ to the beach last weekend.', 'went', ['go', 'goed', 'have gone'], 'last weekend → quá khứ.'), m('She ___ a new laptop yesterday.', 'bought', ['buyed', 'buys', 'buy'], 'buy → bought.'), m('Did you ___ breakfast?', 'have', ['had', 'has', 'having'], 'Sau Did → nguyên mẫu.'), f('They ___ (not / come) to the party. (viết dạng rút gọn)', "didn't come|did not come", 'didn\'t + V.'), m('I ___ him two days ago.', 'saw', ['see', 'seen', 'have seen'], 'ago → quá khứ đơn.'), f('study → V2: ___', 'studied', 'phụ âm + y → ied.')]);
  add('qua-khu-tiep-dien', 'A2', 'Thì quá khứ tiếp diễn', 'Past continuous',
    `${F('S + was/were + V-ing')}<p>Dùng cho việc <b>đang diễn ra</b> tại một thời điểm trong quá khứ, thường kèm một việc khác <b>xen vào</b> (quá khứ đơn).</p>
    ${ex([['I was *sleeping* at *ten* last *night*.', '10 giờ tối qua tôi đang ngủ.'], ['While I was *cooking*, the *phone* *rang*.', 'Trong khi tôi đang nấu ăn thì điện thoại reo.'], ['What were you *doing* when I *called*?', 'Bạn đang làm gì khi tôi gọi?']])}${tip('🔑 <b>when</b> + việc xen vào (quá khứ đơn), <b>while</b> + việc đang diễn ra (tiếp diễn).')}`,
    [m('At 8 p.m. yesterday, I ___ dinner.', 'was having', ['had', 'have', 'were having'], 'Thời điểm cụ thể → đang diễn ra.'), m('They ___ TV when the power went out.', 'were watching', ['was watching', 'watched', 'watching'], 'They → were.'), m('While she was walking home, it ___ to rain.', 'started', ['was starting', 'starts', 'start'], 'Việc xen vào → quá khứ đơn.'), m('I saw him ___ I was waiting for the bus.', 'while', ['when ago', 'during', 'for'], 'while + tiếp diễn.'), f('What ___ you doing at 9 last night?', 'were', 'you → were.'), o('Sắp xếp: “Tôi đang tắm thì anh ấy gọi.”', ['I', 'was', 'taking', 'a shower', 'when', 'he', 'called.'], 'I was taking a shower when he called.')]);
  add('tuong-lai', 'A2', 'Diễn tả tương lai', 'will / be going to / present continuous',
    `${tbl(['Cấu trúc', 'Dùng khi', 'Ví dụ'], [['will + V', 'quyết định ngay lúc nói, dự đoán chung, hứa, đề nghị', "I'll help you. It will rain tomorrow."], ['be going to + V', 'dự định đã có từ trước; dự đoán có dấu hiệu', "I'm going to buy a car. Look at the clouds – it's going to rain."], ['be + V-ing', 'kế hoạch đã sắp xếp (có giờ, có hẹn)', "I'm meeting the client at 3."]])}
    ${ex([['I\'ll *call* you *later*.', 'Lát nữa tôi sẽ gọi cho bạn.'], ['We\'re going to *open* a new *shop*.', 'Chúng tôi định mở cửa hàng mới.'], ['I\'m *flying* to *Seoul* on *Monday*.', 'Thứ Hai tôi bay đi Seoul.']])}`,
    [m('“The phone is ringing.” – “I ___ get it.”', "'ll", ["'m going to", "'m getting", 'am get'], 'Quyết định ngay lúc nói.'), m('Look at those clouds! It ___ rain.', 'is going to', ['will', 'is raining to', 'rains'], 'Có dấu hiệu → going to.'), m('I ___ my dentist at 10 tomorrow. (đã hẹn)', 'am seeing', ['see', 'will to see', 'seen'], 'Kế hoạch đã sắp xếp.'), m('We have decided. We ___ move to Ho Chi Minh City.', 'are going to', ['will', 'move', 'are move'], 'Dự định từ trước.'), m('I think Vietnam ___ win the match.', 'will', ['is going', 'are going to', 'wins to'], 'Dự đoán theo ý kiến → will.'), f('“Đừng lo, tôi sẽ giúp bạn.” → Don\'t worry, I ___ help you.', 'will', 'Lời hứa → will.')]);
  add('so-sanh', 'A2', 'So sánh hơn và nhất', 'Comparatives & superlatives',
    `${tbl(['Tính từ', 'So sánh hơn', 'So sánh nhất'], [['ngắn (1 âm tiết): cheap', 'cheaper than', 'the cheapest'], ['tận cùng -y: easy', 'easier than', 'the easiest'], ['dài: expensive', 'more expensive than', 'the most expensive'], ['bất quy tắc: good / bad / far', 'better / worse / farther', 'the best / the worst / the farthest']])}
    <p>So sánh bằng: <b>as + adj + as</b> (as tall as). Không bằng: <b>not as … as</b>.</p>${ex([['This *phone* is *cheaper* than that *one*.', 'Điện thoại này rẻ hơn cái kia.'], ['It\'s the *best* *restaurant* in *town*.', 'Đó là nhà hàng ngon nhất thị trấn.'], ['She is as *tall* as her *mother*.', 'Cô ấy cao bằng mẹ.']])}${tip('⚠️ Không dùng cả hai: ❌ <i>more cheaper</i>.')}`,
    [m('A laptop is ___ than a tablet.', 'more expensive', ['expensiver', 'most expensive', 'more expensiver'], 'Tính từ dài → more.'), m('This is ___ day of my life!', 'the best', ['the goodest', 'better', 'the most good'], 'good → the best.'), m('My new office is ___ than the old one.', 'bigger', ['more big', 'biger', 'the biggest'], 'big → bigger (gấp đôi g).'), m('Today is ___ than yesterday.', 'worse', ['badder', 'more bad', 'worst'], 'bad → worse.'), f('He is as ___ (tall) as his father.', 'tall', 'as + nguyên dạng + as.'), m('Câu đúng là?', 'Hanoi is colder than Saigon in winter.', ['Hanoi is more colder than Saigon.', 'Hanoi is cold than Saigon.', 'Hanoi is coldest than Saigon.'], 'cold → colder than.')]);
  add('khuyet-thieu-a2', 'A2', 'Động từ khuyết thiếu cơ bản', 'can / could / must / have to / should',
    `${tbl(['Từ', 'Nghĩa', 'Ví dụ'], [['can / can\'t', 'có thể, biết (khả năng); xin phép', 'I can drive. Can I sit here?'], ['could', 'đã có thể (quá khứ); lời nhờ lịch sự', 'Could you help me, please?'], ['must / mustn\'t', 'phải (người nói thấy cần) / cấm', 'You mustn\'t smoke here.'], ['have to / don\'t have to', 'phải (quy định bên ngoài) / không cần', 'I have to wear a uniform. You don\'t have to pay.'], ['should / shouldn\'t', 'nên / không nên', 'You should see a doctor.']])}
    ${F('modal + V nguyên mẫu (không to, không -s)')}${tip('⚠️ <b>mustn\'t</b> (cấm) khác hẳn <b>don\'t have to</b> (không bắt buộc).')}`,
    [m('You ___ park here. It\'s forbidden.', "mustn't", ["don't have to", 'should', 'can'], 'Cấm → mustn\'t.'), m("It's Sunday. I ___ go to work.", "don't have to", ["mustn't", "can't to", 'should'], 'Không bắt buộc.'), m('You look tired. You ___ rest.', 'should', ['must to', 'have', 'could to'], 'Lời khuyên → should.'), m('___ you open the window, please?', 'Could', ['Must', 'Should', 'Have'], 'Lời nhờ lịch sự.'), m('Câu đúng là?', 'She can speak three languages.', ['She cans speak three languages.', 'She can speaks three languages.', 'She can to speak three languages.'], 'can + V nguyên mẫu.'), m('When I was five, I ___ swim.', 'could', ['can', 'must', 'should'], 'Khả năng trong quá khứ.')]);
  add('htht-co-ban', 'A2', 'Hiện tại hoàn thành (cơ bản)', 'Present perfect: ever / never / just / already / yet',
    `${F('S + have/has + V3')}<p>Dùng cho trải nghiệm (không nói thời điểm), việc vừa xong, việc đã/chưa làm tính đến bây giờ.</p>
    ${ex([['Have you ever *been* to *Japan*?', 'Bạn đã từng đến Nhật chưa?'], ['I have just *finished* my *report*.', 'Tôi vừa làm xong báo cáo.'], ['She hasn\'t *replied* *yet*.', 'Cô ấy vẫn chưa trả lời.']])}
    ${tbl(['Từ', 'Vị trí', 'Câu'], [['ever / never', 'trước V3', 'trải nghiệm'], ['just / already', 'trước V3', 'vừa mới / đã rồi'], ['yet', 'cuối câu', 'phủ định, câu hỏi']])}${tip('⚠️ Có thời điểm cụ thể (yesterday, in 2020) thì dùng quá khứ đơn: ❌ <i>I have seen him yesterday.</i>')}`,
    [m('I ___ never ___ sushi.', 'have / eaten', ['has / eaten', 'have / ate', 'did / eat'], 'have + V3.'), m('She ___ just left the office.', 'has', ['have', 'is', 'did'], 'She → has.'), m("Have you finished it ___?", 'yet', ['already', 'just', 'ever'], 'Câu hỏi → yet cuối câu.'), m('Câu đúng là?', 'I saw that film last week.', ['I have seen that film last week.', 'I have saw that film last week.', 'I seen that film last week.'], 'last week → quá khứ đơn.'), f('go → V3: ___', 'gone', 'go – went – gone.'), m('___ you ever been to Phu Quoc?', 'Have', ['Did', 'Has', 'Were'], 'you → Have.')]);
  add('v-ing-to-v-a2', 'A2', 'V-ing và to V cơ bản', 'like doing / want to do',
    `${tbl(['Theo sau là', 'Động từ', 'Ví dụ'], [['V-ing', 'enjoy, finish, mind, practise, avoid, keep', 'I enjoy reading.'], ['to V', 'want, need, decide, hope, plan, would like, learn', 'I want to learn English.'], ['cả hai, nghĩa gần như nhau', 'like, love, hate, start, begin', 'I like swimming / to swim.'], ['V-ing sau giới từ', 'interested in, good at, before, after, without', 'She is good at drawing.']])}`,
    [m('I enjoy ___ in the morning.', 'running', ['to run', 'run', 'ran'], 'enjoy + V-ing.'), m('We decided ___ a new car.', 'to buy', ['buying', 'buy', 'bought'], 'decide + to V.'), m('He is interested ___ photography.', 'in', ['on', 'at', 'for'], 'interested in.'), m('She is good at ___.', 'cooking', ['cook', 'to cook', 'cooks'], 'Sau giới từ → V-ing.'), m('Would you like ___ a drink?', 'to have', ['having', 'have', 'had'], 'would like + to V.'), m('Have you finished ___ the report?', 'writing', ['to write', 'write', 'wrote'], 'finish + V-ing.')]);
  add('trang-tu-tan-suat', 'A2', 'Trạng từ chỉ tần suất', 'always / usually / often / sometimes / never',
    `<p>always (100%) → usually → often → sometimes → rarely → never (0%).</p>${tbl(['Vị trí', 'Ví dụ'], [['trước động từ thường', 'I usually get up at 6.'], ['sau to be', 'She is always late.'], ['giữa trợ động từ và động từ', "I don't often eat out."]])}<p>Hỏi: <b>How often</b> do you…? – Trả lời: once a week, twice a month, every day.</p>${ex([['I *always* *drink* *coffee* in the *morning*.', 'Tôi luôn uống cà phê buổi sáng.'], ['How often do you go to the *gym*?', 'Bạn đi tập gym bao lâu một lần?']])}`,
    [m('Câu đúng là?', 'He is never late.', ['He never is late.', 'Never he is late.', 'He is late never.'], 'Sau to be.'), m('Câu đúng là?', 'I often go jogging.', ['I go often jogging.', 'Often I go jogging always.', 'I go jogging oftenly.'], 'Trước động từ thường.'), m('___ do you visit your parents? – Twice a month.', 'How often', ['How many', 'How long', 'When often'], 'Hỏi tần suất.'), m('“hai lần một tuần” là?', 'twice a week', ['two times in week', 'second a week', 'two week'], 'twice a week.'), f('0% = ___', 'never', 'never.'), m('She ___ eats meat. She is a vegetarian.', 'never', ['always', 'usually', 'often'], 'Người ăn chay → never.')]);
  add('cau-hoi', 'A2', 'Đặt câu hỏi', 'Question forms & question tags',
    `${F('(Từ hỏi) + trợ động từ + S + V?')}${tbl(['Từ hỏi', 'Hỏi về', 'Ví dụ'], [['What', 'cái gì', 'What do you do?'], ['Where', 'ở đâu', 'Where did you go?'], ['When / What time', 'khi nào / mấy giờ', 'When does it start?'], ['Who', 'ai', 'Who is your manager?'], ['Why', 'tại sao', 'Why are you late?'], ['How / How much / How long', 'thế nào / bao nhiêu tiền / bao lâu', 'How long does it take?']])}
    <h4>Câu hỏi đuôi</h4><p>Khẳng định → đuôi phủ định và ngược lại: <i>You are tired, aren't you? She doesn't eat meat, does she?</i></p>${tip('⚠️ Khi hỏi chủ ngữ (Who/What làm chủ ngữ) thì KHÔNG dùng trợ động từ: <i>Who called you?</i> (không phải Who did call you?)')}`,
    [m('___ does the train leave? – At 7:30.', 'What time', ['Where', 'How much', 'Who'], 'Hỏi giờ.'), m('Câu đúng là?', 'Where did you buy it?', ['Where you bought it?', 'Where did you bought it?', 'Where you did buy it?'], 'Trợ động từ + S + V.'), m('You work here, ___?', "don't you", ['do you', "aren't you", "doesn't you"], 'Khẳng định → đuôi phủ định.'), m('She is your sister, ___?', "isn't she", ["doesn't she", 'is she', "isn't her"], 'is → isn\'t she.'), m('___ broke the window? – Tom did.', 'Who', ['Who did', 'Whom', 'Whose'], 'Hỏi chủ ngữ.'), o('Sắp xếp: “Mất bao lâu?”', ['How', 'long', 'does', 'it', 'take?'], 'How long does it take?')]);

  /* ===================== B1 ===================== */
  add('htht-qkd', 'B1', 'Hiện tại hoàn thành và quá khứ đơn', 'for / since, been vs gone',
    `${tbl(['Hiện tại hoàn thành', 'Quá khứ đơn'], [['Kết nối với hiện tại, không nói thời điểm', 'Đã xong, có thời điểm xác định'], ['I have worked here <b>for</b> 5 years / <b>since</b> 2021. (vẫn đang làm)', 'I worked there for 5 years. (giờ không làm nữa)'], ['How long have you…?', 'When did you…?'], ['this week, today (chưa kết thúc), so far, recently', 'yesterday, last…, ago, in 2020']])}
    <p><b>for</b> + khoảng thời gian (for 3 days) · <b>since</b> + mốc (since Monday, since I was a child).<br><b>has been to</b> (đã đến và về rồi) ≠ <b>has gone to</b> (đã đi, chưa về).</p>${ex([['I have *lived* in *Long* *An* since *2018*.', 'Tôi sống ở Long An từ năm 2018.'], ['How long have you *known* each *other*?', 'Hai bạn quen nhau bao lâu rồi?']])}`,
    [m('I have worked at this bank ___ 2019.', 'since', ['for', 'from', 'ago'], 'Mốc → since.'), m('She has been a teacher ___ ten years.', 'for', ['since', 'ago', 'in'], 'Khoảng → for.'), m('We ___ to Hanoi last month.', 'went', ['have gone', 'have been', 'go'], 'last month → quá khứ đơn.'), m('“Where is Nam?” – “He ___ to the bank. He\'ll be back soon.”', 'has gone', ['has been', 'went to ago', 'is been'], 'Đã đi, chưa về.'), m('___ have you worked here?', 'How long', ['When', 'How often', 'What time'], 'Hỏi khoảng thời gian.'), m('I ___ three cups of coffee today.', 'have had', ['had', 'have', 'has had'], 'today chưa hết → HTHT.')]);
  add('htht-tiep-dien', 'B1', 'Hiện tại hoàn thành tiếp diễn', 'Present perfect continuous',
    `${F('S + have/has been + V-ing')}<p>Nhấn mạnh <b>quá trình kéo dài</b> từ quá khứ đến nay (có thể vẫn tiếp tục), hoặc giải thích kết quả đang thấy.</p>${ex([['I have been *waiting* for *two* *hours*!', 'Tôi đã đợi hai tiếng rồi!'], ['You look *tired*. Have you been *working* *late*?', 'Trông bạn mệt. Bạn làm muộn à?']])}
    ${tip('So sánh: <i>I have written 3 emails</i> (kết quả, số lượng) – <i>I have been writing emails all morning</i> (quá trình).')}`,
    [m('It ___ since 6 a.m. The streets are wet.', 'has been raining', ['rains', 'is raining since', 'rained'], 'Quá trình kéo dài đến nay.'), m('How long ___ English?', 'have you been learning', ['are you learning', 'do you learn', 'did you learn since'], 'Kéo dài đến nay.'), m('I ___ five reports today. (số lượng)', 'have written', ['have been writing', 'was writing', 'write'], 'Kết quả, số lượng → HTHT.'), m('Her eyes are red. She ___.', 'has been crying', ['cries', 'has cried yet', 'cried tomorrow'], 'Giải thích dấu hiệu.'), f('They have ___ (work) on this project since March.', 'been working', 'have been + V-ing.')]);
  add('qua-khu-hoan-thanh', 'B1', 'Quá khứ hoàn thành', 'Past perfect',
    `${F('S + had + V3')}<p>Việc xảy ra <b>trước</b> một việc khác trong quá khứ.</p>${ex([['When I *arrived*, the *train* had already *left*.', 'Khi tôi đến thì tàu đã rời đi rồi.'], ['She had never *flown* before that *trip*.', 'Trước chuyến đi đó cô ấy chưa từng đi máy bay.']])}${tip('🔑 Thường đi với: before, after, by the time, already, when.')}`,
    [m('By the time we got there, the film ___.', 'had started', ['started', 'has started', 'starts'], 'Xảy ra trước → had V3.'), m('After she ___ dinner, she went out.', 'had eaten', ['has eaten', 'eats', 'eating'], 'Trước việc went out.'), m('I didn\'t know him because we ___ before.', "hadn't met", ["haven't met", "didn't meet yet", "don't meet"], 'Trước thời điểm quá khứ.'), f('He ___ (finish) the report before the meeting began.', 'had finished', 'had + V3.'), o('Sắp xếp: “Tôi đã quên mật khẩu.” (trước khi đăng nhập)', ['I', 'had', 'forgotten', 'my', 'password.'], 'I had forgotten my password.')]);
  add('dieu-kien-012', 'B1', 'Câu điều kiện loại 0, 1, 2', 'Conditionals 0, 1, 2',
    `${tbl(['Loại', 'Mệnh đề If', 'Mệnh đề chính', 'Dùng khi'], [['0', 'hiện tại đơn', 'hiện tại đơn', 'sự thật luôn đúng'], ['1', 'hiện tại đơn', 'will + V', 'có thể xảy ra ở hiện tại/tương lai'], ['2', 'quá khứ đơn (were cho mọi ngôi)', 'would + V', 'không có thật / khó xảy ra ở hiện tại']])}
    ${ex([['If you *heat* *ice*, it *melts*.', 'Nếu đun nóng đá, nó tan.'], ['If it *rains*, we\'ll *stay* at *home*.', 'Nếu trời mưa, chúng ta sẽ ở nhà.'], ['If I *were* *you*, I would *accept* the *offer*.', 'Nếu tôi là bạn, tôi sẽ nhận lời.']])}${tip('⚠️ Không dùng will trong mệnh đề If: ❌ <i>If it will rain…</i> · <b>unless</b> = if … not.')}`,
    [m('If you ___ hard, you will pass.', 'study', ['will study', 'studied', 'would study'], 'Loại 1: If + hiện tại.'), m('If I had more money, I ___ a new car.', 'would buy', ['will buy', 'buy', 'bought'], 'Loại 2.'), m('If I ___ you, I would talk to her.', 'were', ['am', 'will be', 'be'], 'Loại 2: were.'), m('Water ___ at 100°C if you heat it.', 'boils', ['will boil', 'would boil', 'boiled'], 'Loại 0: sự thật.'), m('We will be late ___ we leave now.', 'unless', ['if', 'when', 'because'], 'unless = if not.'), f('If it ___ (be) sunny tomorrow, we will go to the beach.', 'is', 'Loại 1.')]);
  add('bi-dong', 'B1', 'Câu bị động', 'Passive voice',
    `${F('S + be (chia thì) + V3 (+ by …)')}${tbl(['Thì', 'Bị động', 'Ví dụ'], [['Hiện tại đơn', 'is/are + V3', 'English is spoken worldwide.'], ['Quá khứ đơn', 'was/were + V3', 'The bridge was built in 2010.'], ['Hiện tại hoàn thành', 'has/have been + V3', 'Your order has been shipped.'], ['Tương lai / modal', 'will/can/must be + V3', 'The report must be sent today.'], ['Tiếp diễn', 'is/are being + V3', 'The road is being repaired.']])}
    <p>Dùng khi <b>hành động</b> quan trọng hơn người làm, hoặc không biết ai làm. Rất hay gặp trong email, báo cáo, tin tức.</p>`,
    [m('This house ___ in 1990.', 'was built', ['built', 'is built', 'has built'], 'Quá khứ bị động.'), m('Your package ___ tomorrow.', 'will be delivered', ['will deliver', 'is delivering', 'delivers'], 'Tương lai bị động.'), m('The meeting room ___ at the moment.', 'is being cleaned', ['is cleaning', 'cleans', 'has cleaned'], 'Tiếp diễn bị động.'), m('All the tickets ___ already.', 'have been sold', ['have sold', 'are sell', 'sold been'], 'HTHT bị động.'), f('Rice ___ (grow) in the Mekong Delta.', 'is grown', 'Hiện tại bị động.'), m('The documents must ___ before Friday.', 'be signed', ['sign', 'signed', 'signing'], 'modal + be V3.')]);
  add('menh-de-quan-he', 'B1', 'Mệnh đề quan hệ', 'who / which / that / where / whose',
    `${tbl(['Từ', 'Thay cho', 'Ví dụ'], [['who', 'người', 'The man who called you is my boss.'], ['which', 'vật', 'The laptop which I bought is fast.'], ['that', 'người / vật (mệnh đề xác định)', 'The book that you lent me…'], ['where', 'nơi chốn', 'the town where I grew up'], ['whose', 'sở hữu', 'the girl whose father is a doctor']])}
    <p><b>Không xác định</b> (có dấu phẩy, thêm thông tin): không dùng that. <i>My father, who is 60, still works.</i></p>${tip('💡 Khi đại từ quan hệ làm tân ngữ trong mệnh đề xác định, có thể bỏ: <i>The laptop (that) I bought is fast.</i>')}`,
    [m('The woman ___ lives next door is a nurse.', 'who', ['which', 'where', 'whose'], 'Người → who.'), m('This is the hotel ___ we stayed last year.', 'where', ['which', 'who', 'whose'], 'Nơi chốn + mệnh đề đủ → where.'), m('I have a friend ___ brother is a pilot.', 'whose', ['who', 'which', 'that his'], 'Sở hữu → whose.'), m('Hanoi, ___ is the capital, has many lakes.', 'which', ['that', 'who', 'where'], 'Không xác định → không dùng that.'), m('The phone ___ I bought last week is broken.', 'that', ['who', 'where', 'whose'], 'Vật → that/which.'), o('Sắp xếp: “Người đã giúp tôi là bạn tôi.”', ['The man', 'who', 'helped me', 'is', 'my friend.'], 'The man who helped me is my friend.')]);
  add('tuong-thuat', 'B1', 'Câu tường thuật', 'Reported speech',
    `<p>Thuật lại lời người khác: lùi thì một bậc và đổi đại từ, trạng từ.</p>${tbl(['Lời nói trực tiếp', 'Tường thuật'], [['am/is/are', 'was/were'], ['V (hiện tại đơn)', 'V2 (quá khứ đơn)'], ['will / can', 'would / could'], ['quá khứ đơn / HTHT', 'had V3'], ['today / tomorrow / here', 'that day / the next day / there']])}
    ${ex([['She said (that) she was *busy*.', '“I am busy.” → Cô ấy nói cô ấy bận.'], ['He asked me where I *lived*.', '“Where do you live?” → Câu hỏi tường thuật không đảo ngữ.'], ['The manager told us to *finish* it by *Friday*.', 'Mệnh lệnh → told + O + to V.']])}${tip('⚠️ <b>say</b> + (that) …; <b>tell</b> + người + (that) … ❌ <i>She said me</i>.')}`,
    [m('“I am tired,” he said. → He said he ___ tired.', 'was', ['is', 'were', 'has been'], 'Lùi thì.'), m('“I will call you.” → She said she ___ call me.', 'would', ['will', 'can', 'shall'], 'will → would.'), m('“Where do you work?” → He asked me where ___.', 'I worked', ['did I work', 'do I work', 'I work did'], 'Không đảo ngữ.'), m('She ___ me that she was leaving.', 'told', ['said', 'spoke', 'talked'], 'tell + người.'), m('“Close the door.” → He told me ___ the door.', 'to close', ['close', 'closing', 'closed'], 'told + O + to V.'), m('“Are you OK?” → She asked ___ I was OK.', 'if', ['that', 'what', 'do'], 'Câu hỏi Yes/No → if/whether.')]);
  add('used-to', 'B1', 'Used to và thói quen quá khứ', 'used to / be used to / get used to',
    `${tbl(['Cấu trúc', 'Nghĩa', 'Ví dụ'], [['used to + V', 'đã từng (nay không còn)', 'I used to smoke.'], ['be used to + V-ing / N', 'quen với', "I'm used to working late."], ['get used to + V-ing / N', 'dần quen với', "You'll get used to the weather."]])}`,
    [m('I ___ live in the countryside, but now I live in the city.', 'used to', ['am used to', 'use to living', 'get used to'], 'Đã từng.'), m("She is used to ___ up early.", 'getting', ['get', 'got', 'to get'], 'be used to + V-ing.'), m('Did you ___ play the guitar?', 'use to', ['used to', 'using to', 'be used'], 'Did + use to.'), m("It took me a month to get used to ___ on the left.", 'driving', ['drive', 'drove', 'to drive'], 'get used to + V-ing.'), f('There ___ to be a cinema here. (nay không còn)', 'used', 'used to.')]);
  add('v-ing-to-v-b1', 'B1', 'V-ing và to V đổi nghĩa', 'stop / remember / forget / try',
    `${tbl(['Động từ', '+ to V', '+ V-ing'], [['stop', 'dừng lại để làm việc khác: stop to buy coffee', 'thôi không làm nữa: stop smoking'], ['remember / forget', 'nhớ/quên (việc cần làm): remember to lock the door', 'nhớ/quên (việc đã làm): I remember meeting her'], ['try', 'cố gắng: try to finish', 'thử: try restarting the computer'], ['regret', 'lấy làm tiếc phải báo: regret to inform', 'hối hận đã làm: regret saying that']])}`,
    [m('Please remember ___ the lights before you leave.', 'to turn off', ['turning off', 'turn off', 'turned off'], 'Việc cần làm.'), m('I remember ___ her at the conference last year.', 'meeting', ['to meet', 'meet', 'met'], 'Việc đã làm.'), m('He stopped ___. He is healthier now.', 'smoking', ['to smoke', 'smoke', 'smoked'], 'Thôi làm.'), m('The printer doesn\'t work. Try ___ it off and on again.', 'turning', ['to turn', 'turn', 'turned'], 'Thử làm.'), m('We regret ___ you that your application was unsuccessful.', 'to inform', ['informing', 'inform', 'informed'], 'Tiếc phải báo.')]);
  add('suy-doan', 'B1', 'Động từ khuyết thiếu chỉ suy đoán', 'must / might / may / can\'t',
    `${tbl(['Mức chắc chắn', 'Từ', 'Ví dụ'], [['~ 95% có', 'must', "He's not answering. He must be busy."], ['~ 50%', 'may / might / could', 'She might be at the meeting.'], ['~ 95% không', "can't / couldn't", "That can't be true!"]])}<p>Suy đoán về quá khứ: <b>must/might/can't + have + V3</b> (học kỹ ở B2).</p>`,
    [m('The lights are off. They ___ be at home.', "can't", ['must', 'should', 'have to'], 'Chắc chắn không.'), m('She has three jobs. She ___ be very tired.', 'must', ["can't", 'might not', 'should not'], 'Chắc chắn có.'), m('I\'m not sure where Tom is. He ___ be in the canteen.', 'might', ['must', "can't", 'has to'], '50%.'), m('That ___ be Lan – she\'s in Hue today.', "can't", ['must', 'might', 'should'], 'Không thể.'), f('Take an umbrella. It ___ rain later. (có thể)', 'might|may|could', 'Khả năng.')]);

  /* ===================== B2 ===================== */
  add('dieu-kien-3', 'B2', 'Câu điều kiện loại 3 và hỗn hợp', 'Third & mixed conditionals',
    `${tbl(['Loại', 'If', 'Mệnh đề chính', 'Ý nghĩa'], [['3', 'had + V3', 'would have + V3', 'trái với quá khứ'], ['Hỗn hợp 3→2', 'had + V3', 'would + V', 'quá khứ khác → hiện tại khác'], ['Hỗn hợp 2→3', 'quá khứ đơn', 'would have + V3', 'tính cách/hiện tại → quá khứ đã khác']])}
    ${ex([['If I had *known*, I would have *told* you.', 'Nếu tôi biết thì tôi đã nói với bạn rồi.'], ['If I had *taken* that *job*, I would be *rich* now.', 'Nếu hồi đó nhận việc thì giờ tôi đã giàu.']])}
    <p>Đảo ngữ trang trọng: <b>Had I known</b>, … = If I had known, …</p>`,
    [m('If we had left earlier, we ___ the train.', 'would have caught', ['would catch', 'will catch', 'had caught'], 'Loại 3.'), m('If she ___ harder, she would have passed.', 'had studied', ['studied', 'has studied', 'would study'], 'If + had V3.'), m('If I had saved money, I ___ a house now.', 'would have', ['would have had', 'will have', 'had'], 'Hỗn hợp: kết quả hiện tại.'), m('___ I known about the traffic, I would have taken the train.', 'Had', ['If', 'Have', 'Should'], 'Đảo ngữ.'), m('If he weren\'t so shy, he ___ to her at the party.', 'would have spoken', ['would speak', 'spoke', 'will speak'], 'Hỗn hợp 2→3.')]);
  add('wish', 'B2', 'Câu ước', 'wish / if only',
    `${tbl(['Ước về', 'Cấu trúc', 'Ví dụ'], [['hiện tại', 'wish + quá khứ đơn (were)', 'I wish I spoke Korean.'], ['quá khứ (hối tiếc)', 'wish + had V3', 'I wish I had studied harder.'], ['người khác thay đổi (phàn nàn)', 'wish + would + V', 'I wish you would stop talking.']])}<p><b>If only</b> mang nghĩa mạnh hơn wish.</p>`,
    [m('I wish I ___ taller.', 'were', ['am', 'will be', 'had been tomorrow'], 'Hiện tại → were.'), m('I wish I ___ that email. It was a mistake.', "hadn't sent", ["didn't send", "don't send", "wouldn't send"], 'Hối tiếc quá khứ.'), m('I wish my neighbours ___ so much noise.', "wouldn't make", ["don't make", "hadn't made tomorrow", 'not make'], 'Phàn nàn → would.'), m('If only I ___ more time now!', 'had', ['have', 'will have', 'had had'], 'Hiện tại.'), f('I wish I ___ (can) speak Japanese.', 'could', 'can → could.')]);
  add('bi-dong-nang-cao', 'B2', 'Bị động nâng cao', 'It is said that… / have something done',
    `${tbl(['Cấu trúc', 'Ví dụ', 'Nghĩa'], [['It is said / believed / reported that + mệnh đề', 'It is said that the company will close.', 'Người ta nói rằng…'], ['S + is said / thought + to V / to have V3', 'The company is said to be in trouble.', 'Công ty được cho là đang gặp khó.'], ['have / get + vật + V3', 'I had my laptop repaired.', 'Nhờ người khác làm (sửa laptop)']])}`,
    [m('It ___ that the CEO will resign.', 'is reported', ['reports', 'is reporting', 'reported is'], 'It is reported that.'), m('He is believed ___ the country last week.', 'to have left', ['to leave', 'leaving', 'that left'], 'Việc đã xảy ra → to have V3.'), m('I need to have my car ___.', 'serviced', ['service', 'servicing', 'to service'], 'have + O + V3.'), m('She got her hair ___ yesterday.', 'cut', ['cutting', 'to cut', 'cuts'], 'get + O + V3.'), m('The new product is expected ___ next month.', 'to be launched', ['launching', 'to launch it', 'launched be'], 'Bị động + to be V3.')]);
  add('rut-gon-mdqh', 'B2', 'Rút gọn mệnh đề quan hệ và mệnh đề phân từ', 'Reduced relative & participle clauses',
    `${tbl(['Rút gọn', 'Từ', 'Thành'], [['chủ động', 'The man who is standing there', 'The man standing there'], ['bị động', 'The car which was made in Japan', 'The car made in Japan'], ['sau the first / only / last', 'He was the first person who arrived', 'He was the first person to arrive'], ['mệnh đề phân từ (cùng chủ ngữ)', 'After I had finished the work, I went home.', 'Having finished the work, I went home.']])}`,
    [m('The woman ___ to the manager is my aunt.', 'talking', ['talked', 'to talk', 'who talking'], 'Chủ động → V-ing.'), m('The products ___ in this factory are exported.', 'made', ['making', 'make', 'which making'], 'Bị động → V3.'), m('She was the last person ___ the office.', 'to leave', ['leaving', 'left', 'who leaving'], 'the last + to V.'), m('___ the report, she sent it to her boss.', 'Having written', ['Written', 'Having been written', 'To write'], 'Xong việc trước, cùng chủ ngữ.'), m('___ from the plane, the islands look beautiful.', 'Seen', ['Seeing', 'Having seen', 'To see'], 'Các đảo "được nhìn thấy" → V3.')]);
  add('tuong-lai-nang-cao', 'B2', 'Tương lai tiếp diễn và hoàn thành', 'Future continuous & future perfect',
    `${tbl(['Thì', 'Công thức', 'Ví dụ'], [['Tương lai tiếp diễn', 'will be + V-ing', 'This time tomorrow I will be flying to Tokyo.'], ['Tương lai hoàn thành', 'will have + V3', 'By 2030, I will have paid off my loan.'], ['Tương lai hoàn thành tiếp diễn', 'will have been + V-ing', 'By June, I will have been working here for 10 years.']])}${tip('🔑 <b>by + thời điểm</b> (by Friday, by the time…) là dấu hiệu tương lai hoàn thành.')}`,
    [m('At 9 a.m. tomorrow, I ___ a presentation.', 'will be giving', ['will give', 'will have given', 'give'], 'Đang diễn ra tại thời điểm tương lai.'), m('By the end of this year, we ___ 500 laptops.', 'will have sold', ['will sell', 'will be selling', 'sold'], 'by + mốc → hoàn thành.'), m('Don\'t call at 8 – we ___ dinner.', 'will be having', ['will have had', 'have', 'had'], 'Đang làm lúc đó.'), m('By next month, she ___ here for a year.', 'will have been working', ['will work', 'works', 'is working'], 'Quá trình đến mốc.'), f('By the time you arrive, I ___ (finish) the work.', 'will have finished', 'will have V3.')]);
  add('khuyet-thieu-hoan-thanh', 'B2', 'Động từ khuyết thiếu + have V3', 'should have / must have / could have',
    `${tbl(['Cấu trúc', 'Nghĩa', 'Ví dụ'], [['should have + V3', 'lẽ ra nên (nhưng đã không)', 'You should have told me.'], ["shouldn't have + V3", 'lẽ ra không nên', "I shouldn't have eaten so much."], ['must have + V3', 'chắc hẳn đã', 'She must have forgotten.'], ["can't / couldn't have + V3", 'không thể nào đã', "He can't have finished already."], ['might / could have + V3', 'có lẽ đã / lẽ ra đã có thể', 'You could have been hurt!']])}`,
    [m('I failed the test. I ___ harder.', 'should have studied', ['must have studied', 'should study', 'could study'], 'Hối tiếc.'), m('The ground is wet. It ___ last night.', 'must have rained', ["can't have rained", 'should have rained', 'must rain'], 'Suy đoán chắc chắn.'), m('He ___ the email – he was offline all day.', "can't have read", ['must have read', 'should have read', "can't read"], 'Không thể đã.'), m('Why didn\'t you call me? I ___ you a lift.', 'could have given', ['must have given', 'should give', 'can give'], 'Lẽ ra đã có thể.'), m('You ___ so rude to her. It was unkind.', "shouldn't have been", ["mustn't be", "can't have been", "shouldn't be yesterday"], 'Lẽ ra không nên.')]);
  add('lien-tu', 'B2', 'Từ nối và liên từ', 'although / despite / however / whereas',
    `${tbl(['Ý', 'Theo sau là mệnh đề', 'Theo sau là danh từ / V-ing', 'Đầu câu, có dấu phẩy'], [['tương phản', 'although, even though, while, whereas', 'despite, in spite of', 'However, Nevertheless,'], ['nguyên nhân', 'because, since, as', 'because of, due to, owing to', '—'], ['kết quả', 'so, so … that', '—', 'Therefore, As a result, Consequently,'], ['bổ sung', '—', 'in addition to, besides', 'Moreover, Furthermore, In addition,']])}`,
    [m('___ it was raining, we went out.', 'Although', ['Despite', 'However', 'Because of'], 'Theo sau là mệnh đề.'), m('___ the rain, we went out.', 'Despite', ['Although', 'Even though', 'However'], 'Theo sau là danh từ.'), m('The price is high. ___, the quality is excellent.', 'However', ['Although', 'Despite', 'Because'], 'Đầu câu, có dấu phẩy.'), m('The flight was cancelled ___ bad weather.', 'due to', ['because', 'although', 'so'], 'Theo sau là danh từ.'), m('Sales fell sharply. ___, the company cut costs.', 'As a result', ['Despite', 'Whereas', 'Although'], 'Kết quả.'), m('I prefer tea, ___ my wife prefers coffee.', 'whereas', ['despite', 'however', 'due to'], 'So sánh đối lập.')]);
  add('cum-dong-tu', 'B2', 'Cụm động từ thông dụng', 'Phrasal verbs',
    `${tbl(['Cụm', 'Nghĩa', 'Ví dụ'], [['look into', 'điều tra, xem xét', "We'll look into the problem."], ['carry out', 'tiến hành', 'carry out a survey'], ['put off', 'hoãn', 'The meeting was put off.'], ['set up', 'thành lập, cài đặt', 'set up a company / set up the printer'], ['run out of', 'hết', 'We ran out of paper.'], ['come up with', 'nghĩ ra', 'come up with an idea'], ['deal with', 'xử lý', 'deal with complaints'], ['turn down', 'từ chối; vặn nhỏ', 'turn down an offer'], ['figure out', 'tìm ra, hiểu ra', 'figure out the cause'], ['follow up', 'theo dõi tiếp, liên hệ lại', 'follow up with the client']])}${tip('💡 Cụm tách được: <i>turn it off</i> (đại từ phải ở giữa: ❌ turn off it).')}`,
    [m('The meeting has been ___ until next week.', 'put off', ['put out', 'carried out', 'set up'], 'Hoãn.'), m('We need to ___ a solution quickly.', 'come up with', ['run out of', 'look after', 'put up with'], 'Nghĩ ra.'), m('Our printer has ___ of ink.', 'run out', ['put off', 'turned down', 'set up'], 'Hết.'), m('She ___ the job offer because the salary was low.', 'turned down', ['turned up', 'looked into', 'set off'], 'Từ chối.'), m('The IT team will ___ the network error.', 'look into', ['look forward', 'put off', 'run out'], 'Xem xét.'), m('Câu đúng là?', 'Please turn it off.', ['Please turn off it.', 'Please turn it of.', 'Please off turn it.'], 'Đại từ ở giữa.')]);

  /* ===================== C1 ===================== */
  add('dao-ngu', 'C1', 'Đảo ngữ nhấn mạnh', 'Inversion',
    `<p>Đưa trạng từ phủ định / hạn chế lên đầu câu rồi <b>đảo trợ động từ lên trước chủ ngữ</b> để nhấn mạnh (văn viết, diễn văn).</p>${tbl(['Đầu câu', 'Ví dụ'], [['Never / Rarely / Seldom', 'Never have I seen such a mess.'], ['Not only … but also', 'Not only did he lie, but he also stole.'], ['Hardly / No sooner … than', 'No sooner had I arrived than it started to rain.'], ['Only when / Only after', 'Only when I left did I realise my mistake.'], ['Under no circumstances', 'Under no circumstances should you share your password.'], ['Should / Were / Had (điều kiện)', 'Should you need help, call me.']])}`,
    [m('Never ___ such a beautiful sunset.', 'have I seen', ['I have seen', 'I saw', 'seen I have'], 'Đảo trợ động từ.'), m('Not only ___ late, but he also forgot the documents.', 'was he', ['he was', 'he is', 'did he was'], 'Đảo to be.'), m('Under no circumstances ___ the door unlocked.', 'should you leave', ['you should leave', 'you leave', 'leave you'], 'Đảo modal.'), m('No sooner had she sat down ___ the phone rang.', 'than', ['when', 'then', 'that'], 'No sooner … than.'), m('___ you require further information, please contact us.', 'Should', ['If should', 'Would', 'Had'], 'Should = If.'), m('Only after the meeting ___ the truth.', 'did I learn', ['I learned', 'I did learn', 'learned I'], 'Only after + đảo ở mệnh đề chính.')]);
  add('cau-che', 'C1', 'Câu chẻ nhấn mạnh', 'Cleft sentences',
    `${tbl(['Cấu trúc', 'Ví dụ', 'Nhấn'], [['It is/was … that/who …', 'It was Lan who solved the problem.', 'người/vật được nhấn'], ['What + S + V + is/was …', 'What we need is more time.', 'điều cần nói'], ['All (that) + S + V + is …', 'All I want is a quiet weekend.', 'chỉ một điều'], ['The reason why … is that …', 'The reason why I called is that…', 'lý do']])}`,
    [m('___ was the manager who approved the budget.', 'It', ['That', 'What', 'There'], 'It was … who.'), m('___ I like about this job is the flexibility.', 'What', ['That', 'It', 'Which'], 'What-cleft.'), m('It was in 2015 ___ we first met.', 'that', ['which', 'when it', 'what'], 'It was … that.'), m('All I need ___ a good night\'s sleep.', 'is', ['are', 'be', 'it is'], 'All … is.'), o('Sắp xếp: “Điều chúng ta cần là thêm thời gian.”', ['What', 'we', 'need', 'is', 'more time.'], 'What we need is more time.')]);
  add('gia-dinh', 'C1', 'Thức giả định', 'Subjunctive & It\'s time…',
    `${tbl(['Cấu trúc', 'Ví dụ'], [['suggest / recommend / insist / demand + that + S + V nguyên mẫu', 'I suggest that he take a break.'], ['It is essential / vital / important that + S + V nguyên mẫu', 'It is essential that every staff member attend.'], ["It's (high) time + S + V2", "It's time we left."], ['would rather + S + V2', "I'd rather you didn't smoke here."], ['as if / as though + V2 (không thật)', 'He talks as if he knew everything.']])}`,
    [m('The doctor recommended that she ___ more water.', 'drink', ['drinks', 'drank', 'to drink'], 'Giả định → V nguyên mẫu.'), m('It is vital that the data ___ backed up daily.', 'be', ['is', 'are', 'will be'], 'be nguyên mẫu.'), m("It's high time we ___ home.", 'went', ['go', 'going', 'have gone'], "It's time + V2."), m("I'd rather you ___ tell anyone.", "didn't", ["don't", "won't", 'not'], 'would rather + V2.'), m('He behaves as if he ___ the boss.', 'were', ['is', 'be', 'has been'], 'Không thật.')]);
  add('danh-tu-hoa', 'C1', 'Danh từ hoá và văn phong học thuật', 'Nominalisation',
    `<p>Văn viết trang trọng (báo cáo, IELTS Writing) chuộng <b>danh từ</b> hơn động từ để câu gọn và khách quan.</p>${tbl(['Văn nói', 'Văn viết học thuật'], [['Prices went up quickly.', 'There was a rapid increase in prices.'], ['We decided to cut costs.', 'The decision to cut costs was made.'], ['If people use phones too much, they sleep badly.', 'Excessive phone use leads to poor sleep quality.'], ['The bank analysed the data carefully.', 'A careful analysis of the data was conducted.']])}${tip('📝 Cặp động từ → danh từ cần thuộc: increase/an increase, decline/a decline, improve/improvement, develop/development, decide/decision, fail/failure, analyse/analysis.')}`,
    [m('Danh từ của “analyse” là?', 'analysis', ['analyses', 'analysing', 'analyst'], 'analysis.'), m('“Unemployment rose sharply.” → There was a sharp ___ in unemployment.', 'rise', ['rose', 'raise', 'rising up'], 'a rise in.'), m('Danh từ của “fail” là?', 'failure', ['failing', 'fail', 'failness'], 'failure.'), m('Câu nào trang trọng hơn?', 'The implementation of the policy was delayed.', ['They delayed doing the policy.', 'The policy got delayed a lot, you know.', 'They did the policy late.'], 'Danh từ hoá.'), f('decide → danh từ: ___', 'decision', 'decision.')]);
  add('hedging', 'C1', 'Nói giảm, rào đón', 'Hedging & softening',
    `<p>Văn học thuật và giao tiếp chuyên nghiệp tránh khẳng định tuyệt đối.</p>${tbl(['Thay vì', 'Hãy nói'], [['This is the cause.', 'This appears to be / may be one of the main causes.'], ['Everyone agrees.', 'It is widely believed that…'], ['Your plan is wrong.', "I'm not sure this plan would work as well as we hope."], ['Prices will rise.', 'Prices are likely to rise.']])}${tbl(['Nhóm', 'Ví dụ'], [['động từ', 'seem, appear, tend to, suggest, indicate'], ['tính từ/trạng từ', 'likely, possible, arguably, relatively, to some extent'], ['cụm', 'It could be argued that…, There is some evidence that…']])}`,
    [m('Câu nào mang tính rào đón (hedging)?', 'The results suggest that the method may be effective.', ['The method is effective.', 'The method is 100% effective.', 'Everyone knows the method works.'], 'suggest, may.'), m('Young people ___ to spend more time online than older adults.', 'tend', ['are tend', 'tending', 'tends'], 'tend to.'), m('It could be ___ that technology isolates people.', 'argued', ['argue', 'arguing', 'argument'], 'It could be argued.'), m('Cách góp ý lịch sự hơn: “Your report has mistakes.”', 'There seem to be a few minor issues in the report.', ['Your report is bad.', 'You made many mistakes again.', 'Fix your report.'], 'Rào đón, giảm nhẹ.'), f('Sales are ___ to increase next year. (có khả năng)', 'likely', 'be likely to.')]);
  add('collocation', 'C1', 'Kết hợp từ tự nhiên', 'Collocations',
    `<p>Người bản xứ nói <i>make a decision</i>, không nói <i>do a decision</i>. Dùng đúng kết hợp từ là bước nhảy từ B2 lên C1.</p>${tbl(['Động từ', 'Đi với'], [['make', 'a decision, a mistake, progress, an effort, a profit, an appointment'], ['do', 'business, research, your best, damage, a favour'], ['take', 'action, responsibility, a risk, place, advantage of'], ['pay', 'attention, a visit, a compliment'], ['meet', 'a deadline, a need, expectations']])}${tbl(['Tính từ + danh từ', ''], [['heavy traffic / heavy rain', 'không nói strong traffic'], ['strong coffee / strong evidence', 'không nói powerful coffee'], ['high price / low cost', 'không nói expensive price'], ['a fast-growing economy', '—']])}`,
    [m('We need to ___ a decision today.', 'make', ['do', 'take place', 'give'], 'make a decision.'), m('Our company ___ business with many banks.', 'does', ['makes', 'takes', 'pays'], 'do business.'), m('The conference will ___ place in Da Nang.', 'take', ['make', 'do', 'have'], 'take place.'), m('There was ___ traffic on the way to work.', 'heavy', ['strong', 'big', 'thick'], 'heavy traffic.'), m('We worked overtime to ___ the deadline.', 'meet', ['do', 'make', 'reach at'], 'meet a deadline.'), m('Please ___ attention to the safety rules.', 'pay', ['make', 'do', 'take'], 'pay attention.')]);

  window.PLT_EN_GRAM = G;
})();
